dataSource.sql:
SELECT count(*) * (SELECT a.web_session_sample_rate FROM dash_demo.as_of a) AS estimated_sessions
FROM dash_demo.web_sessions s
WHERE true
  AND s.started_ts >= ${dateFrom}
  AND s.started_ts < ${dateTo__next_day}
  AND s.device IN (${device})

SELECT round(count(CASE WHEN s.purchased THEN 1 END) * 1.0 / count(*), 4) AS conversion_rate
FROM dash_demo.web_sessions s
WHERE true
  AND s.started_ts >= ${dateFrom}
  AND s.started_ts < ${dateTo__next_day}
  AND s.device IN (${device})
